  "image_category": "SIGN_ILLUSTRATION",
  "summary": "Hình ảnh minh họa ba biển báo cấm theo QCVN 41:2024/BGTVT: P.106a (cấm xe ô tô tải), P.106b (cấm xe ô tô tải có khối lượng chuyên chở vượt ngưỡng), và P.106c (cấm xe chở hàng nguy hiểm).",
  "items": [
    {
      "identifier": "Biển số P.106a",
      "visual_or_geometric_features": "Hình tròn viền đỏ, nền trắng, biểu tượng xe ô tô tải màu đen ở giữa, có dấu gạch chéo đỏ cắt ngang",
      "meaning_or_specification": "Báo đường cấm các loại xe ô tô tải trừ các xe được ưu tiên theo quy định; có hiệu lực cấm cả máy kéo và xe máy chuyên dùng đi vào đoạn đường đặt biển."
    },
    {
      "identifier": "Biển số P.106b",
      "visual_or_geometric_features": "Hình tròn viền đỏ, nền trắng, biểu tượng xe ô tô tải màu đen với chữ số '25t' màu trắng trên thân xe, có dấu gạch chéo đỏ cắt ngang",
      "meaning_or_specification": "Báo đường cấm các loại xe ô tô tải có khối lượng chuyên chở lớn hơn giá trị ghi trên biển (ví dụ: 25 tấn); có hiệu lực cấm cả máy kéo và xe máy chuyên dùng đi vào đoạn đường đặt biển."
    },
    {
      "identifier": "Biển số P.106c",
      "visual_or_geometric_features": "Hình tròn viền đỏ, nền trắng, biểu tượng xe tải chở thùng hàng màu cam (hoặc vàng) ở giữa, có dấu gạch chéo đỏ cắt ngang",
      "meaning_or_specification": "Báo đường cấm các xe chở hàng nguy hiểm; áp dụng cho toàn bộ đoạn đường đặt biển."
    }
  ]
